markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# Keep source template object.
for r,vals in [(11,[4,4,4,4,4,4,8,5,8,4,4,4,4]),(12,[4,4,4,4,4,4,8,5,8,4,4,4,4]),(13,[4,4,4,4,4,4,8,5,0,4,4,4,4])]:
    g[r]=vals
# Place a copy centered on each scattered 1.
for r,c in markers:
    for i in range(3):
        for j in range(3):
            rr,cc=r+i-1,c+j-1
            if 0<=rr<H and 0<=cc<W:
                g[rr][cc]=t[i][j]
print('\n'.join(' '.join(map(str,row)) for row in g))

